1	//! KNOWN_MODELS capability lookup for Gemini models.
2	
3	use paigasus_helikon_core::ModelCapabilities;
4	
5	/// Capability snapshot for a model id.
6	#[derive(Debug, Clone, Copy)]
7	pub(crate) struct ModelEntry {
8	    pub(crate) caps: ModelCapabilities,
9	}
10	
11	/// Conservative fallback for ids absent from [`KNOWN_MODELS`].
12	pub(crate) const fn conservative_defaults() -> ModelEntry {
13	    ModelEntry {
14	        caps: ModelCapabilities::empty().with_streaming().with_tools(),
15	    }
16	}
17	
18	const fn full() -> ModelEntry {
19	    ModelEntry {
20	        caps: ModelCapabilities::empty()
21	            .with_streaming()
22	            .with_tools()
23	            .with_parallel_tool_calls()
24	            .with_structured_output()
25	            .with_vision(),
26	    }
27	}
28	
29	/// Capability snapshot keyed by exact model id. Cross-check against Google's
30	/// published model docs at implementation time; divergences are bugs.
31	pub(crate) const KNOWN_MODELS: &[(&str, ModelEntry)] = &[
32	    ("gemini-2.5-pro", full()),
33	    ("gemini-2.5-flash", full()),
34	    ("gemini-2.0-flash", full()),
35	    ("gemini-2.0-flash-lite", full()),
36	];
37	
38	/// Look up capabilities for `model_id`, falling back to conservative defaults.
39	pub(crate) fn lookup(model_id: &str) -> ModelEntry {
40	    KNOWN_MODELS
41	        .iter()
42	        .find(|(id, _)| *id == model_id)
43	        .map(|(_, e)| *e)
44	        .unwrap_or_else(conservative_defaults)
45	}
46	
47	#[cfg(test)]
48	mod tests {
49	    use super::*;
50	
51	    #[test]
52	    fn known_25_flash_has_tools_and_structured_output() {
53	        let e = lookup("gemini-2.5-flash");
54	        assert!(e.caps.streaming && e.caps.tools && e.caps.structured_output && e.caps.vision);
55	        assert!(e.caps.parallel_tool_calls);
56	        // Reasoning streaming deferred (D3): flag stays false even for 2.5.
57	        assert!(!e.caps.reasoning);
58	    }
59	
60	    #[test]
61	    fn unknown_model_falls_back_to_conservative() {
62	        let e = lookup("gemini-9-ultra");
63	        assert!(e.caps.streaming && e.caps.tools);
64	        assert!(!e.caps.structured_output);
65	    }
66	}
