36	impl<'a> OpenCalls<'a> {
37	    fn new(items: &'a [Item]) -> Self {
38	        let mut all = HashSet::new();
39	        for it in items {
40	            match it {
41	                Item::ToolCall { call_id, .. } => {
42	                    all.insert(call_id.as_str());
43	                }
44	                Item::AssistantMessage { content, .. } => {
45	                    for p in content {
46	                        if let ContentPart::ToolUse { call_id, .. } = p {
47	                            all.insert(call_id.as_str());
48	                        }
49	                    }
50	                }
51	                _ => {}
52	            }
53	        }
54	        Self {
55	            open: Vec::new(),
56	            seen: HashSet::new(),
57	            all,
58	        }
59	    }
