408	/// Text of the `user` turn that follows a trailing `model` turn.
409	///
410	/// Gemini rejects a request whose last turn is a model turn. The core
411	/// structured-output finalizing request ends with the model's own answer, so
412	/// the translator appends this turn for Gemini 3 and later.
413	pub(crate) const TRAILING_MODEL_TURN_PROMPT: &str = "Continue.";
414	
415	/// Put [`DUMMY_THOUGHT_SIGNATURE`] on each `functionCall` part of a `model`
416	/// content in the current turn when none of its calls has a signature.
417	///
418	/// The current turn is every content after the last `user` content with no
419	/// `functionResponse` part (all contents when there is no such content).
420	/// Gemini checks signatures only in that turn. A content with at least one
421	/// signature is sent as received.
422	fn add_dummy_signatures(merged: &mut [(&'static str, Vec<Part>)]) {
423	    let start = merged
424	        .iter()
425	        .rposition(|(role, parts)| *role == "user" && !parts.iter().any(Part::is_response))
426	        .map_or(0, |i| i + 1);
427	    for (role, parts) in &mut merged[start..] {
428	        if *role != "model" {
429	            continue;
430	        }
431	        let has_call = parts.iter().any(Part::is_call);
432	        let has_signature = parts
433	            .iter()
434	            .any(|p| p.is_call() && p.json.get("thoughtSignature").is_some());
435	        if !has_call || has_signature {
436	            continue;
437	        }
438	        for p in parts.iter_mut().filter(|p| p.is_call()) {
439	            p.json["thoughtSignature"] = Value::String(DUMMY_THOUGHT_SIGNATURE.to_owned());
440	        }
441	    }
442	}
