454	/// Translate the parts of an `Item::UserMessage`.
455	///
456	/// Handles the Anthropic-native [`ContentPart::ToolResult`] shape (a tool
457	/// result carried inside a user turn) by emitting a `functionResponse` part,
458	/// recovering the function name from the earliest open call with that id
459	/// exactly like the top-level [`Item::ToolResult`] branch. A duplicate result
460	/// (no open call left) is dropped with a warning. Text and base64 images translate as usual;
461	/// URL images and other parts are dropped with a discriminant warning.
462	fn user_parts<'a>(
463	    content: &'a [ContentPart],
464	    calls: &mut OpenCalls<'a>,
465	) -> Result<Vec<Value>, ModelError> {
466	    let mut out = Vec::new();
467	    for p in content {
468	        match p {
469	            // The translator drops empty text, as SMA-804 spec section 5.3
470	            // asks every translator to do.
471	            ContentPart::Text { text } if text.is_empty() => {}
472	            ContentPart::Text { text } => out.push(json!({ "text": text })),
473	            ContentPart::Image {
474	                source: MediaSource::Base64 { mime_type, data },
475	            } => {
476	                out.push(json!({ "inlineData": { "mimeType": mime_type, "data": data } }));
477	            }
478	            // Provider data is valid only in an assistant message.
479	            ContentPart::ProviderData { .. } => {}
480	            ContentPart::ToolResult { call_id, content } => {
481	                if let Some(name) = calls.close(call_id)? {
482	                    out.push(json!({
483	                        "functionResponse": {
484	                            "id": call_id,
485	                            "name": name,
486	                            "response": tool_response_object(content),
487	                        }
488	                    }));
489	                }
490	            }
491	            other => {
492	                tracing::warn!(
493	                    target: "paigasus::gemini::translate",
494	                    part = ?std::mem::discriminant(other),
495	                    "unsupported content part; skipping"
496	                );
497	            }
498	        }
499	    }
500	    Ok(out)
501	}
