534	/// Reduce a tool result's content parts to a JSON object for `functionResponse.response`.
535	fn tool_response_object(content: &[ContentPart]) -> Value {
536	    let text: String = content
537	        .iter()
538	        .filter_map(|p| match p {
539	            ContentPart::Text { text } => Some(text.as_str()),
540	            _ => None,
541	        })
542	        .collect::<Vec<_>>()
543	        .join("");
544	    match serde_json::from_str::<Value>(&text) {
545	        Ok(Value::Object(m)) => Value::Object(m),
546	        Ok(other) => json!({ "result": other }),
547	        Err(_) => json!({ "result": text }),
548	    }
549	}
