16	/// Fully-assembled Gemini request body.
17	#[derive(Debug)]
18	pub(crate) struct PreparedRequest {
19	    pub(crate) body: Value,
20	}
21	
22	/// Assemble the Gemini `generateContent` request body, running all guards.
23	pub(crate) fn build_request(
24	    cfg: &Config,
25	    req: &ModelRequest,
26	) -> Result<PreparedRequest, ModelError> {
27	    let s = &req.model_settings;
28	
29	    validate_conflict(
30	        s.response_format.as_ref(),
31	        &req.tools,
32	        s.tool_choice.as_ref(),
33	    )?;
34	
35	    // tool_choice Tool/Required require tools.
36	    if matches!(
37	        s.tool_choice,
38	        Some(paigasus_helikon_core::ToolChoice::Required)
39	            | Some(paigasus_helikon_core::ToolChoice::Tool { .. })
40	    ) && req.tools.is_empty()
41	    {
42	        return Err(ModelError::Other(anyhow::anyhow!(
43	            "tool_choice requires at least one tool"
44	        )));
45	    }
46	
47	    // tool_choice Tool{name} must reference a declared tool.
48	    if let Some(paigasus_helikon_core::ToolChoice::Tool { name }) = &s.tool_choice {
49	        if !req.tools.iter().any(|tool| tool.name == *name) {
50	            return Err(ModelError::Other(anyhow::anyhow!(
51	                "tool_choice references unknown tool `{name}`"
52	            )));
53	        }
54	    }
55	
56	    let translated = items_to_contents(&req.messages, &cfg.model_id, cfg.transport.api_name())?;
57	    let mut body = Map::new();
58	    body.insert("contents".into(), Value::Array(translated.contents));
59	    if let Some(sys) = translated.system {
60	        body.insert("systemInstruction".into(), sys);
61	    }
62	
63	    let decls = function_declarations(&req.tools);
64	    if !decls.is_empty() {
65	        body.insert("tools".into(), Value::Array(decls));
66	    }
67	    let all_names: Vec<String> = req.tools.iter().map(|t| t.name.clone()).collect();
68	    if let Some(fcc) = function_calling_config(s.tool_choice.as_ref(), &all_names) {
69	        body.insert(
70	            "toolConfig".into(),
71	            serde_json::json!({ "functionCallingConfig": fcc }),
72	        );
73	    }
74	
75	    let mut gen = Map::new();
76	    if let Some(t) = s.temperature {
77	        gen.insert("temperature".into(), serde_json::json!(t));
78	    }
79	    if let Some(p) = s.top_p {
80	        gen.insert("topP".into(), serde_json::json!(p));
81	    }
82	    if let Some(m) = s.max_output_tokens {
83	        gen.insert("maxOutputTokens".into(), serde_json::json!(m));
84	    }
85	    if let Some((mime, schema)) = response_format_fields(s.response_format.as_ref()) {
86	        gen.insert("responseMimeType".into(), Value::String(mime));
87	        if let Some(sc) = schema {
88	            gen.insert("responseSchema".into(), sc);
89	        }
90	    }
91	    if !gen.is_empty() {
92	        body.insert("generationConfig".into(), Value::Object(gen));
93	    }
94	
95	    Ok(PreparedRequest {
96	        body: Value::Object(body),
97	    })
98	}
