1	//! Build per-transport request URLs and auth headers.
2	
3	use paigasus_helikon_core::ModelError;
4	
5	use crate::auth::Auth;
6	use crate::builder::{Config, Transport};
7	
8	/// Host for the selected transport, honoring `base_url`.
9	fn host(cfg: &Config) -> String {
10	    if let Some(b) = &cfg.base_url {
11	        return b.trim_end_matches('/').to_owned();
12	    }
13	    match &cfg.transport {
14	        Transport::Developer => "https://generativelanguage.googleapis.com".to_owned(),
15	        Transport::Vertex { location, .. } if location == "global" => {
16	            "https://aiplatform.googleapis.com".to_owned()
17	        }
18	        Transport::Vertex { location, .. } => {
19	            format!("https://{location}-aiplatform.googleapis.com")
20	        }
21	    }
22	}
23	
24	/// Streaming endpoint URL (`:streamGenerateContent?alt=sse`).
25	pub(crate) fn stream_url(cfg: &Config) -> String {
26	    let host = host(cfg);
27	    match &cfg.transport {
28	        Transport::Developer => format!(
29	            "{host}/v1beta/models/{}:streamGenerateContent?alt=sse",
30	            cfg.model_id
31	        ),
32	        Transport::Vertex { project, location } => format!(
33	            "{host}/v1/projects/{project}/locations/{location}/publishers/google/models/{}:streamGenerateContent?alt=sse",
34	            cfg.model_id
35	        ),
36	    }
37	}
38	
39	/// Auth header for a non-async credential (`ApiKey`/`Bearer`).
40	pub(crate) fn auth_header(
41	    auth: &Auth,
42	) -> Result<(reqwest::header::HeaderName, String), ModelError> {
43	    use reqwest::header::{HeaderName, AUTHORIZATION};
44	    match auth {
45	        Auth::ApiKey(k) => Ok((HeaderName::from_static("x-goog-api-key"), k.clone())),
46	        Auth::Bearer(b) => Ok((AUTHORIZATION, format!("Bearer {b}"))),
47	        Auth::Token(_) => Err(ModelError::Other(anyhow::anyhow!(
48	            "Auth::Token must be resolved before auth_header"
49	        ))),
50	    }
51	}
