213	// ---- LlmAgent end-to-end (SMA-827) ----
214	
215	use std::sync::atomic::{AtomicUsize, Ordering};
216	use std::sync::{Arc, Mutex};
217	
218	use paigasus_helikon_core::{
219	    Agent, AgentInput, LlmAgent, RunContext, RunResultStreaming, StopReason, Tool, ToolContext,
220	    ToolError, ToolOutput,
221	};
222	
223	/// A tool that counts its calls and returns the step it got.
224	struct StepTool {
225	    calls: Arc<AtomicUsize>,
226	    /// The `n` of each invocation, in order.
227	    seen: Arc<Mutex<Vec<i64>>>,
228	    schema: serde_json::Value,
229	}
230	
231	impl StepTool {
232	    fn new() -> (Self, Arc<AtomicUsize>) {
233	        let calls = Arc::new(AtomicUsize::new(0));
234	        let tool = Self {
235	            calls: Arc::clone(&calls),
236	            seen: Arc::new(Mutex::new(Vec::new())),
237	            schema: serde_json::json!({
238	                "type":"object","properties":{"n":{"type":"integer"}},"required":["n"]
239	            }),
240	        };
241	        (tool, calls)
242	    }
243	}
244	
245	#[async_trait::async_trait]
246	impl Tool<()> for StepTool {
247	    fn name(&self) -> &str {
248	        "step"
249	    }
250	    fn description(&self) -> &str {
251	        "Run step n. Returns the step number."
252	    }
253	    fn schema(&self) -> &serde_json::Value {
254	        &self.schema
255	    }
256	    async fn invoke(
257	        &self,
258	        _ctx: &ToolContext<()>,
259	        args: serde_json::Value,
260	    ) -> Result<ToolOutput, ToolError> {
261	        self.calls.fetch_add(1, Ordering::SeqCst);
262	        if let Some(n) = args["n"].as_i64() {
263	            self.seen.lock().unwrap().push(n);
264	        }
265	        // For n=1 the result holds a value the model cannot guess.
